package com.dreamcore.workspace.knowledge;
import com.dreamcore.workspace.identity.*;
import com.dreamcore.workspace.material.MaterialAccess;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Explicit non-permission proposals, resolved by the source file's current maintainer. */
@Service
public class GovernanceProposalService {
 public record Patch(List<String> tags,String summary,List<WikiLearningService.Evidence> evidence,String executionClass,String modelName) {}
 public record Create(UUID requestId,UUID versionId,int expectedRevision,String kind,List<String> tags,String summary,UUID draftId,String reason) {}
 public record Resolve(UUID requestId,String decision) {}
 public record Item(UUID id,UUID tenantId,UUID materialId,String sourceName,String kind,String status,boolean stale,Patch patch,String reason,UUID actorId,UUID resolvedBy,String createdAt,String resolvedAt) {}
 public record Page(List<Item> items,boolean hasMore) {}
 public record Preparation(UUID versionId,int version,Integer generation,int tagsRevision,int summaryRevision,List<String> tags,String summary,String summaryExecutionClass,boolean canMaintain) {}
 private final org.springframework.jdbc.core.JdbcTemplate db;private final IdentityService identities;private final MaterialAccess access;private final MaterialGovernanceService governance;private final WikiLearningService learning;private final IdentityAudit audit;
 private final tools.jackson.databind.json.JsonMapper json=new tools.jackson.databind.json.JsonMapper();
 public GovernanceProposalService(JdbcTemplate db,IdentityService identities,MaterialAccess access,MaterialGovernanceService governance,WikiLearningService learning,IdentityAudit audit){this.db=db;this.identities=identities;this.access=access;this.governance=governance;this.learning=learning;this.audit=audit;}
 private IdentityException missing(){return new IdentityException(404,"MATERIAL_NOT_FOUND");}
 private IdentityException changed(){return new IdentityException(409,"GOVERNANCE_PROPOSAL_CHANGED");}
 private Map<String,Object> source(UUID actor,UUID tenant,UUID material,boolean write){identities.member(actor,tenant,false);var rows=db.queryForList("SELECT m.name,m.workspace_id,v.id version_id,v.number FROM active_materials m JOIN workspaces w ON w.id=m.workspace_id JOIN material_versions v ON v.material_id=m.id AND v.number=m.current_version WHERE m.id=? AND m.tenant_id=? AND m.in_library AND w.kind='SHARED'",material,tenant);if(rows.isEmpty())throw missing();var r=rows.getFirst();access.requireObject(actor,tenant,(UUID)r.get("workspace_id"),"MATERIAL",material,write);return r;}
 private int summaryRevision(UUID material){return db.queryForObject("SELECT coalesce(max(revision),0) FROM material_summary_versions WHERE material_id=?",Integer.class,material);}
 private boolean same(UUID actor,UUID tenant,UUID material,UUID version,UUID run){var s=source(actor,tenant,material,false);if(!version.equals(s.get("version_id")))return false;if(run!=null){try{learning.source(actor,tenant,material,version,run);}catch(IdentityException e){if(e.status==409)return false;throw e;}}return true;}
 @Transactional public Preparation prepare(UUID actor,UUID tenant,UUID material){var s=source(actor,tenant,material,false);var g=governance.detail(actor,tenant,material);var runs=db.queryForList("SELECT generation,status FROM knowledge_runs WHERE version_id=? ORDER BY generation DESC LIMIT 1",s.get("version_id"));Integer generation=runs.isEmpty()||!Set.of("READY","PARTIAL").contains(runs.getFirst().get("status"))?null:(Integer)runs.getFirst().get("generation");var rows=db.queryForList("SELECT s.summary,s.version_id,s.run_id,p.patch->>'executionClass' execution_class FROM material_summary_versions s JOIN material_governance_proposals p ON p.id=s.proposal_id WHERE s.material_id=? ORDER BY s.revision DESC LIMIT 1",material);String summary=null,execution=null;if(!rows.isEmpty()){var r=rows.getFirst();if(same(actor,tenant,material,(UUID)r.get("version_id"),(UUID)r.get("run_id"))){summary=(String)r.get("summary");execution=(String)r.get("execution_class");}}return new Preparation((UUID)s.get("version_id"),(Integer)s.get("number"),generation,g.revision(),summaryRevision(material),g.tags(),summary,execution,g.canEdit());}
 private void text(String value,int max){if(value==null||value.isBlank()||value.length()>max||value.codePoints().anyMatch(c->Character.isISOControl(c)&&c!=9&&c!=10&&c!=13))throw IdentityException.invalid();}
 @Transactional public Item create(UUID actor,UUID tenant,UUID material,Create body){
  if(body==null||body.requestId()==null||body.versionId()==null||body.expectedRevision()<0||!Set.of("TAGS","SUMMARY").contains(body.kind()==null?"":body.kind()))throw IdentityException.invalid();text(body.reason(),500);
  identities.member(actor,tenant,false,false);db.queryForList("SELECT id FROM tenants WHERE id=? FOR UPDATE",tenant);source(actor,tenant,material,true);
  String fp=IdentityService.hash(tenant+"\n"+material+"\n"+json.writeValueAsString(body));var prior=identities.priorRequest(actor,body.requestId(),"GOVERNANCE_PROPOSE",fp);if(prior!=null)return detail(actor,tenant,prior);
  var p=prepare(actor,tenant,material);if(!p.versionId().equals(body.versionId())||body.expectedRevision()!=(body.kind().equals("TAGS")?p.tagsRevision():p.summaryRevision()))throw changed();
  Patch patch;UUID run=null;
  if(body.kind().equals("TAGS")){if(body.tags()==null||body.tags().isEmpty()||body.tags().size()>12||body.summary()!=null||body.draftId()!=null)throw IdentityException.invalid();body.tags().forEach(t->text(t,40));patch=new Patch(body.tags().stream().map(String::strip).distinct().toList(),null,List.of(),null,null);}
  else {if(body.tags()!=null)throw IdentityException.invalid();text(body.summary(),2000);String execution=null,model=null;var evidence=List.<WikiLearningService.Evidence>of();if(body.draftId()!=null){var d=learning.detail(actor,tenant,body.draftId());if(!d.materialId().equals(material)||!d.versionId().equals(body.versionId())||!d.status().equals("SUCCEEDED")||d.article()==null)throw changed();run=db.queryForObject("SELECT run_id FROM wiki_learning_drafts WHERE id=?",UUID.class,body.draftId());learning.source(actor,tenant,material,body.versionId(),run);evidence=d.article().evidence();execution=d.executionClass();model=d.modelName();}patch=new Patch(null,body.summary().strip(),evidence,execution,model);}
  UUID id=UUID.randomUUID();db.update("INSERT INTO material_governance_proposals(id,tenant_id,material_id,version_id,run_id,base_revision,kind,patch,reason,actor_id) VALUES (?,?,?,?,?,?,?,?::jsonb,?,?)",id,tenant,material,body.versionId(),run,body.expectedRevision(),body.kind(),json.writeValueAsString(patch),body.reason().strip(),actor);identities.remember(actor,body.requestId(),"GOVERNANCE_PROPOSE",fp,id);audit.record(actor,tenant,"GOVERNANCE_PROPOSE",id,"SUCCESS");return detail(actor,tenant,id);
 }
 private Map<String,Object> row(UUID actor,UUID tenant,UUID id){identities.member(actor,tenant,false);var rows=db.queryForList("SELECT *,patch::text payload FROM material_governance_proposals WHERE id=? AND tenant_id=?",id,tenant);if(rows.isEmpty())throw missing();var r=rows.getFirst();source(actor,tenant,(UUID)r.get("material_id"),true);return r;}
 @Transactional public Item detail(UUID actor,UUID tenant,UUID id){var r=row(actor,tenant,id);UUID material=(UUID)r.get("material_id");var s=source(actor,tenant,material,true);boolean stale=!same(actor,tenant,material,(UUID)r.get("version_id"),(UUID)r.get("run_id"));if(r.get("status").equals("PENDING")){int current=r.get("kind").equals("TAGS")?governance.detail(actor,tenant,material).revision():summaryRevision(material);stale|=current!=(Integer)r.get("base_revision");}return new Item(id,tenant,material,(String)s.get("name"),(String)r.get("kind"),(String)r.get("status"),stale,stale||r.get("payload")==null?null:json.readValue((String)r.get("payload"),Patch.class),stale?null:(String)r.get("reason"),(UUID)r.get("actor_id"),(UUID)r.get("resolved_by"),r.get("created_at").toString(),r.get("resolved_at")==null?null:r.get("resolved_at").toString());}
 @Transactional public Item resolve(UUID actor,UUID tenant,UUID id,Resolve body){
  if(body==null||body.requestId()==null||!Set.of("APPROVE","REJECT").contains(body.decision()==null?"":body.decision()))throw IdentityException.invalid();identities.member(actor,tenant,false,false);db.queryForList("SELECT id FROM tenants WHERE id=? FOR UPDATE",tenant);var r=row(actor,tenant,id);
  String fp=IdentityService.hash(tenant+"\n"+id+"\n"+body.decision());UUID prior=identities.priorRequest(actor,body.requestId(),"GOVERNANCE_RESOLVE",fp);if(prior!=null)return detail(actor,tenant,id);if(!r.get("status").equals("PENDING"))throw changed();
  var d=detail(actor,tenant,id);if(body.decision().equals("APPROVE")){
   if(d.stale()||d.patch()==null)throw changed();var p=prepare(actor,tenant,d.materialId());
   if(d.kind().equals("TAGS")){var g=governance.detail(actor,tenant,d.materialId());governance.change(actor,tenant,d.materialId(),new MaterialGovernanceService.Change(UUID.nameUUIDFromBytes(("proposal:"+id).getBytes(java.nio.charset.StandardCharsets.UTF_8)),p.version(),p.tagsRevision(),d.patch().tags(),g.reviewAt()),false);}
   else db.update("INSERT INTO material_summary_versions(material_id,revision,proposal_id,version_id,run_id,summary,actor_id) VALUES (?,?,?,?,?,?,?)",d.materialId(),p.summaryRevision()+1,id,r.get("version_id"),r.get("run_id"),d.patch().summary(),actor);
  }
  db.update("UPDATE material_governance_proposals SET status=?,resolved_by=?,resolved_at=now() WHERE id=?",body.decision().equals("APPROVE")?"APPLIED":"REJECTED",actor,id);identities.remember(actor,body.requestId(),"GOVERNANCE_RESOLVE",fp,id);audit.record(actor,tenant,"GOVERNANCE_"+body.decision(),id,"SUCCESS");return detail(actor,tenant,id);
 }
 @Transactional public Page list(UUID actor,UUID tenant,String status,int offset){if(!Set.of("ALL","PENDING","APPLIED","REJECTED").contains(status)||offset<0||offset>100000)throw IdentityException.invalid();identities.member(actor,tenant,false);var ids=db.queryForList("SELECT p.id FROM material_governance_proposals p JOIN active_materials m ON m.id=p.material_id JOIN workspaces w ON w.id=m.workspace_id WHERE p.tenant_id=? AND m.in_library AND w.kind='SHARED' AND (?='ALL' OR p.status=?) AND (library_mask(?,p.tenant_id,'MATERIAL',m.id)&3)=3 ORDER BY p.created_at DESC,p.id LIMIT 21 OFFSET ?",UUID.class,tenant,status,status,actor,offset);return new Page(ids.stream().limit(20).map(id->detail(actor,tenant,id)).toList(),ids.size()>20);}
}
